window.products.push({"id":1093769,"name":"Arts & Crafts Black Student Desk by Home Styles","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/31zZr+UkCAL._AC_.jpg","description":"Arts and crafts student desk is made of poplar solids and engineered wood. Comes with multi-step black finish. Student desk embellishes typical mission styling with framed doors showcasing raised wood, lattice moldings on the two storage drawers and slightly flared legs. The drop front center drawer can also be used as a keyboard tray with two additional storage drawers on each side. Easy to assemble. Measures 42-inch width by 24-inch depth by 30-inch height.","images":["https://m.media-amazon.com/images/I/31zZr+UkCAL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Home Styles","source_asin":"B005H7Z3H6","category_path":"Home & Kitchen"},"sku":"BM-1093769","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B005H7Z3H6","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B005H7Z3H6","price_pending":true,"merchant_ready":false});
